    imgr.removeEntryIndexOperation(wd2);
    SearchOperation search3 = new SearchOperation(imgr);
    search3.setTerm("Enterprise");
    imgr.executeIndexOperationNow(search3);
    assertEquals(0, search3.getResultsCount());
}

